class Program{static string Decode(string s)=>s=="-"?null:s=="."?"":Encoding.UTF8.GetString(Convert.FromHexString(s));static string Hex(string s)=>s==null?"-":s.Length==0?".":Convert.ToHexString(Encoding.UTF8.GetBytes(s)).ToLowerInvariant();static void Main(){var store=new SQLiteFriendsData("Data Source=:memory:","Friends");var connection=(SQLiteConnection)typeof(SQLiteGenericTableHandler<FriendsData>).GetField("m_Connection",BindingFlags.Static|BindingFlags.NonPublic).GetValue(null);using(var create=connection.CreateCommand()){create.CommandText="CREATE TABLE Friends (PrincipalID CHAR(36) NOT NULL, Friend VARCHAR(255) NOT NULL, Flags VARCHAR(16) NOT NULL DEFAULT 0, Offered VARCHAR(32) NOT NULL DEFAULT 0, PRIMARY KEY(PrincipalID,Friend))";create.ExecuteNonQuery();}string line;while((line=Console.ReadLine())!=null){try{var p=line.Split(' ');string principal=Decode(p[1]);if(p[0]=="s"){var row=new FriendsData{PrincipalID=principal,Friend=Decode(p[2]),Data=new Dictionary<string,string>{{"Flags",Decode(p[3])}}};if(p[4]!="!")row.Data["Offered"]=Decode(p[4]);Console.Write(store.Store(row)?"T":"F");}else if(p[0]=="d")Console.Write(store.Delete(principal,Decode(p[2]))?"T":"F");else{var rows=store.GetFriends(principal);Console.Write(rows.Length);foreach(var r in rows)Console.Write("|"+Hex(r.PrincipalID)+":"+Hex(r.Friend)+":"+Hex(r.Data["Flags"])+":"+Hex(r.Data["Offered"])+":"+Hex(r.Data["TheirFlags"]));}Console.WriteLine();}catch{Console.WriteLine("E");}}}}
